def test_index_sparql_sends_get_and_parses_terms(client, httpx_mock):
    httpx_mock.add_response(
        json=load_fixture_json("sparql_index.json"), headers=JSON_HEADERS
    )
    result = client.index.sparql(SELECT_QUERY)
    request = last_request(httpx_mock)
    assert request.method == "GET"
    assert str(request.url).startswith("https://sparql.opencitations.net/index?")
    assert request.url.params["query"] == SELECT_QUERY
    assert request.headers["accept"] == "application/sparql-results+json"
    assert result.head.vars == ["ci", "citing", "cited"]
    assert result.results is not None
    assert result.results.bindings[0]["ci"].type == "uri"
    assert result.rows()[0]["ci"] == "https://w3id.org/oc/index/ci/0601-061203747253"
    assert result.meta == {"query-time-ms": 214, "result-size-total": 2}
    assert result.boolean is None


def test_meta_sparql_keeps_datatypes(client, httpx_mock):
    httpx_mock.add_response(
        json=load_fixture_json("sparql_meta.json"), headers=JSON_HEADERS
    )
    result = client.meta.sparql(SELECT_QUERY)
    request = last_request(httpx_mock)
    assert str(request.url).startswith("https://sparql.opencitations.net/meta?")
    assert request.url.params["query"] == SELECT_QUERY
    assert result.results is not None
    date = result.results.bindings[0]["date"]
    assert date.datatype == "http://www.w3.org/2001/XMLSchema#gYearMonth"
    assert date.value == "1999-10"
    assert result.results.bindings[1]["title"].datatype is None
    assert result.rows()[1]["date"] == "1999-05-01"


def test_language_tag_and_bnode_terms(client, httpx_mock):
    httpx_mock.add_response(
        json={
            "head": {"vars": ["label", "node"]},
            "results": {
                "bindings": [
                    {
                        "label": {
                            "type": "literal",
                            "value": "Titel",
                            "xml:lang": "de",
                        },
                        "node": {"type": "bnode", "value": "bn404814857120584000"},
                    }
                ]
            },
        },
        headers=JSON_HEADERS,
    )
    result = client.meta.sparql(SELECT_QUERY)
    assert result.results is not None
    binding = result.results.bindings[0]
    assert binding["label"].xml_lang == "de"
    assert binding["label"].model_dump(by_alias=True) == {
        "type": "literal",
        "value": "Titel",
        "datatype": None,
        "xml:lang": "de",
    }
    assert binding["node"].type == "bnode"


